[Form]
public class METOrderExtractScreenParameters extends FormRun
{
    METOrderExtractScreenParameters   metOrderExtractScreenParameters;

}

    public void closeOk()
    {
        // Only save the parameters when valid, so on reopen the parameters match what is displayed in the form
        metOrderExtractScreenParameters.parmRoute(filterMETRoute.valueStr());
        metOrderExtractScreenParameters.parmSite(filterSite.valueStr());
        metOrderExtractScreenParameters.parmWarehouse(filterInventLocationId.valueStr());
        metOrderExtractScreenParameters.parmShippingDateConfirmFrom(filterSalesShippingDateConfirmedfrom.dateValue());
        metOrderExtractScreenParameters.parmShippingDateConfirmTo(filterSalesShippingDateConfirmedTo.dateValue());
        metOrderExtractScreenParameters.parmCategory(filterCategory.valueStr());
        metOrderExtractScreenParameters.parmExtracted(filterExtractStatus.selection());

        metOrderExtractScreenParameters.saveLastValue(formStr(METOrderExtractScreen));

        if (element.args()
            &&  element.args().caller()
            &&  element.args().caller() is FormRun
            &&  formHasMethod(element.args().caller(), identifierStr(refresh)))
        {
            element.args().caller().refresh();
        }

        super();
    }

   /// <summary>
   /// Validate the confirmed ship date
   /// </summary>
   /// <returns>true if the date is valid otherwise false</returns>
    public boolean validateShipDate()
    {
        boolean ret = true;

        if(filterSalesShippingDateConfirmedFrom.dateValue() > filterSalesShippingDateConfirmedTo.dateValue())
        {
            ret = checkFailed("@MET:ConfirmShipDateError");
        }

        return ret;
    }

    public void init()
    {
        Object caller;
        FormRun callerForm;

        super();

        caller = this.args().caller();
        callerForm = caller as FormRun;

        if (metOrderExtractScreenParameters == null)
        {
            metOrderExtractScreenParameters = METOrderExtractScreenParameters::construct();
            metOrderExtractScreenParameters.loadLastValue(formStr(METOrderExtractScreen));
        }

        filterMETRoute.text(metOrderExtractScreenParameters.parmRoute());
        filterSite.text(metOrderExtractScreenParameters.parmSite());
        filterInventLocationId.text(metOrderExtractScreenParameters.parmWarehouse());
        filterSalesShippingDateConfirmedFrom.dateValue(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()));
        filterSalesShippingDateConfirmedTo.dateValue(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()));
        filterCategory.text(metOrderExtractScreenParameters.parmCategory());
    }

        /// <summary>
        /// Warehouse site lookup
        /// </summary>
        public void lookup()
        {
            //Specify the name of the table the lookup should show data from.
            SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), this);
            //Create a new query
            Query                   query = new Query();
            QueryBuildDataSource    queryBuildDataSource;
            QueryBuildRange         queryBuildRange;
 
            //Specify the name of the table the lookup should show data from.
            queryBuildDataSource = query.addDataSource(tableNum(InventLocation));
            if (filterSite.valueStr())
            {
                //Filter the data on the InventSiteId field on the InventLocation table.
                queryBuildRange = queryBuildDataSource.addRange(fieldNum(InventLocation,InventSiteId));
                //Only show records where the filterSite field matches the value in

                queryBuildRange.value(queryValue(filterSite.valueStr()));
            }

            //Specify which fields should be shown  in the lookup form.
            //  field returned is the first field referenced
            sysTableLookup.addLookupfield(fieldNum(InventLocation, InventLocationId));
            sysTableLookup.addLookupfield(fieldNum(InventLocation, Name));
            sysTableLookup.addLookupfield(fieldNum(InventLocation, InventSiteId));
 
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }

        /// <summary>
        /// Set the site
        /// </summary>
        /// <returns>true/false</returns>
        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            filterSite.text(InventLocation::find(filterInventLocationId.valueStr()).InventSiteId);
        
            return ret;
        }

        /// <summary>
        /// validate ship date
        /// </summary>
        /// <returns>true/false</returns>
        public boolean modified()
        {
            boolean ret;
    
            ret = super();

            ret = ret && element.validateShipDate();
    
            return ret;
        }

    /// <summary>
    /// validate ship date
    /// </summary>
    /// <returns>true/fasle</returns>
    public boolean modified()
    {
        boolean ret;

        ret = super();
        ret = ret && element.validateShipDate();

        return ret;
    }

        /// <summary>
        /// Warehouse category lookup
        /// </summary>
        public void lookup()
        {
            //Specify the name of the table the lookup should show data from.
            SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(WHSFilters), this);
            //Create a new query
            Query                   query = new Query();
            QueryBuildDataSource    queryBuildDataSource;
            QueryBuildRange         queryBuildRange;
 
            //Specify the name of the table the lookup should show data from.
            queryBuildDataSource = query.addDataSource(tableNum(WHSFilters));
            //Filter the data on the FilterTitle field on the rsmModel table.
            queryBuildRange = queryBuildDataSource.addRange(fieldNum(WHSFilters,FilterTitle));
            //Only show records where the FilterTitle field matches the value in
            //WHSFilterTitle::Code1.
            queryBuildRange.value(queryValue(WHSFilterTitle::Code1));

            //Specify which fields should be shown  in the lookup form.
            //  field returned is the first field referenced
            sysTableLookup.addLookupfield(fieldNum(WHSFilters, FilterNum));
            sysTableLookup.addLookupfield(fieldNum(WHSFilters, FilterTitle));
            sysTableLookup.addLookupfield(fieldNum(WHSFilters, Description));
 
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }
